package com.techlab.app;
import com.techlab.excepciones.ProductoNoEncontradoException; import com.techlab.excepciones.StockInsuficienteException; import com.techlab.pedidos.LineaPedido; import com.techlab.pedidos.Pedido; import com.techlab.productos.Producto; import com.techlab.productos.ProductoElectronico; import com.techlab.servicios.PedidoService; import com.techlab.servicios.ProductoService;
import java.util.LinkedHashMap; import java.util.List; import java.util.Map; import java.util.Scanner;
public class Main {
    private static final Scanner sc=new Scanner(System.in); private static final ProductoService productos=new ProductoService(); private static final PedidoService pedidos=new PedidoService(productos);
    public static void main(String[] args){ int op; System.out.println("Sistema de Gestión - TechLab"); do { menu(); op=entero("Elegí una opción: "); try { switch(op){ case 1 -> agregar(); case 2 -> listarProductos(); case 3 -> buscarActualizar(); case 4 -> eliminar(); case 5 -> crearPedido(); case 6 -> listarPedidos(); case 7 -> System.out.println("¡Hasta luego!"); default -> System.out.println("Opción inválida."); } } catch(ProductoNoEncontradoException|StockInsuficienteException|IllegalArgumentException e){ System.out.println("ERROR: "+e.getMessage()); } System.out.println(); } while(op!=7); }
    private static void menu(){ System.out.println("======================================"); System.out.println("       SISTEMA DE GESTIÓN - TECHLAB"); System.out.println("======================================"); System.out.println("1) Agregar producto"); System.out.println("2) Listar productos"); System.out.println("3) Buscar / Actualizar producto"); System.out.println("4) Eliminar producto"); System.out.println("5) Crear pedido"); System.out.println("6) Listar pedidos"); System.out.println("7) Salir"); }
    private static void agregar(){ String n=texto("Nombre del producto: "); double p=decimal("Precio: "); int s=entero("Stock inicial: "); int tipo=entero("¿Es electrónico? 1) Sí  2) No: "); Producto prod; if(tipo==1)prod=new ProductoElectronico(n,p,s,entero("Meses de garantía: ")); else if(tipo==2)prod=new Producto(n,p,s); else throw new IllegalArgumentException("Tipo inválido."); productos.agregarProducto(prod); System.out.println("Agregado: "+prod.getDescripcionCompleta()); }
    private static void listarProductos(){ if(productos.listarProductos().isEmpty()){System.out.println("No hay productos.");return;} for(Producto p:productos.listarProductos())System.out.println(p.getDescripcionCompleta()); }
    private static void buscarActualizar()throws ProductoNoEncontradoException { int modo=entero("Buscar por 1) ID  2) Nombre: "); if(modo==1){ Producto p=productos.buscarPorId(entero("ID: ")); System.out.println(p.getDescripcionCompleta()); if(siNo("¿Actualizar precio o stock? (s/n): "))actualizar(p); } else if(modo==2){ List<Producto> encontrados=productos.buscarPorNombre(texto("Nombre o parte del nombre: ")); if(encontrados.isEmpty()){System.out.println("Sin resultados.");return;} for(Producto p:encontrados)System.out.println(p.getDescripcionCompleta()); if(encontrados.size()==1&&siNo("¿Actualizar este producto? (s/n): "))actualizar(encontrados.get(0)); } else throw new IllegalArgumentException("Modo inválido."); }
    private static void actualizar(Producto p){ int c=entero("Actualizar 1) Precio  2) Stock  3) Ambos: "); if(c<1||c>3)throw new IllegalArgumentException("Opción inválida."); if(c==1||c==3)p.setPrecio(decimal("Nuevo precio: ")); if(c==2||c==3)p.setStock(entero("Nuevo stock: ")); System.out.println("Actualizado: "+p.getDescripcionCompleta()); }
    private static void eliminar()throws ProductoNoEncontradoException { int id=entero("ID a eliminar: "); Producto p=productos.buscarPorId(id); if(siNo("¿Confirmás eliminar "+p.getNombre()+"? (s/n): ")){productos.eliminarPorId(id);System.out.println("Producto eliminado.");}else System.out.println("Cancelado."); }
    private static void crearPedido()throws ProductoNoEncontradoException,StockInsuficienteException { listarProductos(); int n=entero("¿Cuántos productos diferentes tendrá el pedido? "); if(n<=0)throw new IllegalArgumentException("Ingresá al menos un producto."); Map<Integer,Integer> cantidades=new LinkedHashMap<>(); for(int i=1;i<=n;i++){System.out.println("Producto #"+i);int id=entero("ID: ");int cant=entero("Cantidad: ");if(cantidades.putIfAbsent(id,cant)!=null)throw new IllegalArgumentException("No repitas el mismo ID.");} Pedido pedido=pedidos.crearPedido(cantidades); System.out.println("PEDIDO CREADO CORRECTAMENTE"); imprimir(pedido); }
    private static void listarPedidos(){ if(pedidos.listarPedidos().isEmpty()){System.out.println("Todavía no hay pedidos.");return;} for(Pedido p:pedidos.listarPedidos())imprimir(p); }
    private static void imprimir(Pedido p){ System.out.println("--------------------------------------"); System.out.println("Pedido #"+p.getId()+" | Fecha: "+p.getFechaFormateada()); for(LineaPedido l:p.getLineas())System.out.printf("%s | Cantidad: %d | Unitario: $%.2f | Subtotal: $%.2f%n",l.getProducto().getNombre(),l.getCantidad(),l.getPrecioUnitario(),l.getSubtotal()); System.out.printf("TOTAL: $%.2f%n",p.getTotal()); }
    private static String texto(String m){while(true){System.out.print(m);String v=sc.nextLine().trim();if(!v.isEmpty())return v;System.out.println("No puede quedar vacío.");}}
    private static int entero(String m){while(true){System.out.print(m);try{return Integer.parseInt(sc.nextLine().trim());}catch(NumberFormatException e){System.out.println("Ingresá un entero válido.");}}}
    private static double decimal(String m){while(true){System.out.print(m);try{double v=Double.parseDouble(sc.nextLine().trim().replace(',','.'));if(Double.isFinite(v)&&v>=0)return v;}catch(NumberFormatException ignored){}System.out.println("Ingresá un precio válido no negativo.");}}
    private static boolean siNo(String m){while(true){System.out.print(m);String v=sc.nextLine().trim().toLowerCase();if(v.equals("s")||v.equals("si")||v.equals("sí"))return true;if(v.equals("n")||v.equals("no"))return false;System.out.println("Respondé s/n.");}}
}